/**
 * Normalizes domain key to authoritative canonical key
 */
function canonicalizeDomainKey(rawDomain) {
  if (!rawDomain || typeof rawDomain !== 'string') return 'fullstack';
  const clean = rawDomain.trim().toLowerCase();
  if (clean.includes('datascience') || clean.includes('data science') || clean.includes('machine learning')) return 'datascience';
  if (clean.includes('dsa') || clean.includes('algorithm') || clean.includes('data structure') || clean.includes('interview prep')) return 'dsa';
  if (clean.includes('devops') || clean.includes('cloud')) return 'devops';
  if (clean.includes('cyber') || clean.includes('security') || clean.includes('hacking')) return 'cybersecurity';
  if (clean.includes('mobile') || clean.includes('react native') || clean.includes('flutter') || clean.includes('ios') || clean.includes('android')) return 'mobile';
  if (clean.includes('ai') || clean.includes('llm') || clean.includes('genai') || clean.includes('rag')) return 'ai_llm';
  if (clean.includes('system design') || clean.includes('system_design') || clean.includes('architecture') || clean.includes('microservice')) return 'system_design';
  return 'fullstack';
}

/**
 * Returns topics for given domain
 */
function getDomainTopics(rawDomain) {
  const domainKey = canonicalizeDomainKey(rawDomain);
  return DOMAIN_TOPICS[domainKey] || DOMAIN_TOPICS.fullstack;
}

/**
 * Returns cognitive difficulty distribution ratios based on declared user level
 */
function getDifficultyDistribution(userLevel, questionCount) {
  const lvl = (userLevel || 'BEGINNER').toUpperCase();
  let begRatio = 0.7;
  let intRatio = 0.3;
  let advRatio = 0.0;
  let expRatio = 0.0;

  if (lvl === 'INTERMEDIATE') {
    begRatio = 0.2;
    intRatio = 0.6;
    advRatio = 0.2;
    expRatio = 0.0;
  } else if (lvl === 'ADVANCED') {
    begRatio = 0.0;
    intRatio = 0.2;
    advRatio = 0.6;
    expRatio = 0.2;
  } else if (lvl === 'EXPERT') {
    begRatio = 0.0;
    intRatio = 0.1;
    advRatio = 0.3;
    expRatio = 0.6;
  }

  const begCount = Math.round(questionCount * begRatio);
  const advCount = Math.round(questionCount * advRatio);
  const expCount = Math.round(questionCount * expRatio);
  const intCount = questionCount - (begCount + advCount + expCount);

  return {
    BEGINNER: Math.max(0, begCount),
    INTERMEDIATE: Math.max(0, intCount),
    ADVANCED: Math.max(0, advCount),
    EXPERT: Math.max(0, expCount)
  };
}

/**
 * Fisher-Yates array shuffle helper
 */
function shuffleArray(arr) {
  const array = [...arr];
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

/**
 * Validates individual question object integrity
 */
function validateQuestionObject(q) {
  if (!q || typeof q !== 'object') return false;
  if (!q.question || typeof q.question !== 'string' || !q.question.trim()) return false;
  if (!Array.isArray(q.options) || q.options.length !== 4) return false;
  if (q.options.some(opt => opt === undefined || opt === null || String(opt).trim() === '')) return false;

  const correct = q.correct !== undefined ? q.correct : q.correct_answer;
  if (typeof correct === 'number') {
    if (correct < 0 || correct > 3) return false;
  } else if (Array.isArray(correct)) {
    if (correct.length === 0 || correct.some(idx => idx < 0 || idx > 3)) return false;
  } else if (typeof correct === 'string') {
    if (!correct.trim()) return false;
  } else {
    return false;
  }

  return true;
}

/**
 * Safely shuffles option choices while updating the correct answer index mapping
 */
function shuffleOptionsAndRemapCorrect(q) {
  if (!validateQuestionObject(q)) return q;
  const options = [...q.options];
  const rawCorrect = q.correct !== undefined ? q.correct : q.correct_answer;

  let correctOptionTexts = [];
  if (typeof rawCorrect === 'number' && options[rawCorrect] !== undefined) {
    correctOptionTexts = [String(options[rawCorrect])];
  } else if (Array.isArray(rawCorrect)) {
    correctOptionTexts = rawCorrect.map(idx => options[idx] !== undefined ? String(options[idx]) : null).filter(Boolean);
  } else {
    correctOptionTexts = [String(rawCorrect)];
  }

  const indexedOptions = options.map((text, originalIndex) => ({ text, originalIndex }));
  const shuffled = shuffleArray(indexedOptions);

  const newOptions = shuffled.map(o => o.text);
  let newCorrect = 0;

  if (Array.isArray(rawCorrect)) {
    newCorrect = shuffled
      .map((item, newIdx) => correctOptionTexts.includes(String(item.text)) ? newIdx : -1)
      .filter(idx => idx !== -1);
  } else {
    const foundIdx = shuffled.findIndex(item => String(item.text) === correctOptionTexts[0]);
    newCorrect = foundIdx !== -1 ? foundIdx : 0;
  }

  return {
    ...q,
    options: newOptions,
    correct: newCorrect,
    correct_answer: newCorrect
  };
}

/**
 * Controlled Random Question Selection from Pool
 */
function filterAndSelectCandidateQuestions(domain, level, questionCount = 10, userHistoryIds = []) {
  // Always return empty pool so quiz generation relies purely on dynamic Groq AI generation
  return {
    questions: [],
    totalAvailable: 0,
    domainKey: canonicalizeDomainKey(domain),
    level: level || 'BEGINNER'
  };
}



module.exports = {
  DOMAIN_TOPICS,
  QUESTION_BANK,
  canonicalizeDomainKey,
  getDomainTopics,
  getDifficultyDistribution,
  validateQuestionObject,
  shuffleOptionsAndRemapCorrect,
  filterAndSelectCandidateQuestions
};
